def max_continuous_rests(hours):
    max_rest = current_rest = 0
    for hour in hours:
        if hour == 0:
            current_rest += 1
            max_rest = max(max_rest, current_rest)
        else:
            current_rest = 0
    return max_rest

# Example usage:
# hours = [1, 0, 1, 0, 1]
# print(max_continuous_rests(hours))  # Output: 2

def max_consecutive_rests(n, schedule):
    max_rest = current_rest = 0
    for hour in schedule:
        if hour == 1:
            current_rest += 1
            if current_rest > max_rest:
                max_rest = current_rest
        else:
            current_rest = 0
    return max_rest

# Example usage:
n = int(input())
schedule = list(map(int, input().split()))
print(max_consecutive_rests(n, schedule))
